css:
.chat-widget {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  height: 100%;
  background: transparent;
  padding: 8px 12px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  position: relative;
  gap: 16px;
}

.message-item {
  display: flex;
  align-items: center;
  width: 100%;
  gap: 10px;
  position: relative;
  z-index: 2;
}

.avatar-container {
  flex-shrink: 0;
}

.avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.8);
}

.message-bubble {
  flex: 1;
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-radius: 24px;
  padding: 6px 26px; /* 上下内边距进一步减小，左右进一步增大 */
  display: flex;
  justify-content: space-between;
  align-items: center;
  cursor: pointer;
  transition: all 0.2s ease;
  min-height: 32px; /* 最小高度再次降低 */
}

.message-bubble:active {
  transform: scale(0.98);
  background: rgba(255, 255, 255, 0.8);
}

.message-text {
  color: #555555;
  font-size: 14px;
  letter-spacing: 0.5px;
}

.status-icon {
  font-size: 16px;
  font-weight: 500;
}

.status-icon.checked {
  color: #888888;
}

.status-icon.unchecked {
  color: #aaaaaa;
}

.connecting-line {
  position: absolute;
  left: 34px;
  top: -8px; /* 第一个头像上方的竖线拉长 */
  bottom: 22px; /* 只到第二个头像中心位置 */
  width: 2px;
  background: rgba(255, 255, 255, 0.6);
  z-index: 1;
}
